CREATE OR ALTER PROCEDURE [dbo].[SP_ActivateUser] @UserId INT, @IsActive BIT AS BEGIN SET NOCOUNT OFF; BEGIN TRY UPDATE [USER_MASTER] SET [IS_ACTIVE] = @IsActive WHERE [UM_CODE] = @UserId AND [ES_DELETE] = 0 END TRY BEGIN CATCH DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE() DECLARE @ErrorSeverity INT = ERROR_SEVERITY() DECLARE @ErrorState INT = ERROR_STATE() RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState) END CATCH END